"""

    /// Decoded land bits, row-major `cells[r*cols + c]`. LSB-first per byte,
    /// matching the Android packer.
    static let cells: [Bool] = {
        let cleaned = packedB64.replacingOccurrences(of: "\n", with: "")
        guard let bytes = Data(base64Encoded: cleaned) else {
            return [Bool](repeating: false, count: cols * rows)
        }
        var out = [Bool](repeating: false, count: cols * rows)
        var i = 0
        for b in bytes {
            let v = Int(b)
            var bit = 0
            while bit < 8 && i < out.count {
                out[i] = ((v >> bit) & 1) == 1
                bit += 1; i += 1
            }
        }
        return out
    }()

    static func rowCount() -> Int { rows }
    static func colCount() -> Int { cols }

    /// True if mask cell (r, c) is land. Wraps longitude, clamps latitude.
    static func isLandCell(_ r: Int, _ c: Int) -> Bool {
        if r < 0 || r >= rows { return false }
        let cc = ((c % cols) + cols) % cols
        return cells[r * cols + cc]
    }
}
